        "Множина — die Besuche. Гостей зазвичай позначають одниною без артикля: Wir bekommen Besuch (до нас прийдуть гості); гостювання: zu Besuch sein (бути в гостях).",
        "Людину, яка перебуває в гостях, називають der Gast; der Besuch — це дія або всі ті, хто приходить."
