        "Форми: er bleibt, blieb, ist geblieben. У Perfekt допоміжне дієслово — sein, а не haben: Ich bin zu Hause geblieben.",
        "Після bleiben може стояти місце або прикметник; з інфінітивом воно утворює вирази: stehen bleiben (зупинитися), sitzen bleiben (залишатися сидіти)."
