        "Euch — також зворотний займенник при ihr: Setzt euch! (сідайте!), Freut ihr euch auf die Ferien? Звертаючись до людей ввічливо на «Ви», вживають Sie, Ihnen, а не euch.",
        "Називний відмінок — ihr, родовий (рідко) — euer."
