      "explanation": [
        "Головна думка: geben означає давати комусь щось. Типова будова: jemandem (давальний відмінок, кому?) etwas (знахідний відмінок, що?): Ich gebe dir das Buch.",
        "Форми: du gibst, er gibt (e → i), gab, hat gegeben. Вираз es gibt + знахідний відмінок означає «є, існує»: Es gibt hier ein Café.",
        "Також: eine Antwort geben (відповісти), Hausaufgaben geben (задавати домашнє завдання), die Hand geben (потиснути руку)."
      ],
