        "Окремо: der Großvater (дідусь), die Großmutter (бабуся); у розмовному мовленні der Opa і die Oma. Форми однини Großeltern немає.",
        "У давальному відмінку множини форма не змінюється (слово вже закінчується на -n): bei den Großeltern, mit den Großeltern."
