        "Вживання: in den Laden gehen (іти до магазину), im Laden einkaufen. У складних словах: Blumenladen (квітковий магазин), Bioladen, Schreibwarenladen. Великий магазин називають Supermarkt.",
        "Der Fensterladen (множина die Fensterläden) — віконниця. Дієслово laden (завантажувати, заряджати) пишеться так само, але це дієслово: Ich lade mein Handy."
