      "translation": "пробувати • спробувати • куштувати • скуштувати",
      "explanation": [
        "Головна думка: probieren означає «пробувати, спробувати» (щось нове) і «куштувати» (їжу, напій): Probier mal die Suppe! Ich möchte den Kuchen probieren.",
        "Форми: probiert, probierte, hat probiert (без ge-, бо дієслово закінчується на -ieren). Зазвичай зі знахідним відмінком: etwas probieren. Похідне з відокремлюваним префіксом: anprobieren (приміряти одяг).",
        "Ввічливо разом із mal: Probier mal! — Спробуй!"
      ],
      "examples": [
        {
          "de": "Probier mal die Suppe!",
          "lv": "Скуштуй суп!"
        },
        {
          "de": "Ich möchte den Kuchen probieren.",
          "lv": "Я хотів би скуштувати пиріг."
        },
        {
          "de": "Wir probieren eine neue Methode.",
          "lv": "Ми пробуємо новий метод."
        },
        {
          "de": "Kann ich die Jacke anprobieren?",
          "lv": "Можна приміряти куртку?"
        }
      ],
      "comparison": [
        {
          "word": "versuchen",
          "meaning": "намагатися",
          "example": "Ich versuche zu schlafen. – Я намагаюся заснути."
        },
        {
          "word": "kosten",
          "meaning": "куштувати; коштувати",
          "example": "Kosten Sie bitte den Wein. – Скуштуйте, будь ласка, вино."
        },
        {
          "word": "anprobieren",
          "meaning": "приміряти",
          "example": "Ich probiere die Schuhe an. – Я приміряю туфлі."
        }
      ],
      "tip": [
        "Probieren — спробувати їжу або щось нове; versuchen — намагатися щось зробити: Ich versuche zu kommen.",
        "Mal додають для м’якості: Probier mal! (спробуй)."
      ],
      "important": [
        "Probieren не означає «намагатися»; для цього є versuchen.",
        "У Perfekt немає ge-: hat probiert, а не «hat geprobiert»."
      ],
