        "Українською це може бути «якщо» (умова: wenn du willst) або «коли» (повторення чи момент у майбутньому: immer wenn, wenn ich Zeit habe). Якщо підрядне речення стоїть першим, у головному реченні дієслово йде одразу після коми.",
        "Одноразову подію в минулому виражають не через wenn, а через als: Als ich klein war ..."
